150	/// Split raw bytes into records on LF (0x0a). The separator is not part of
151	/// any record. A trailing LF terminates the last record without adding an
152	/// empty one; an empty file yields zero records.
153	fn split_records(data: &[u8]) -> Vec<&[u8]> {
154	    if data.is_empty() {
155	        return Vec::new();
156	    }
157	    let mut records: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
158	    if data.last() == Some(&b'\n') {
159	        records.pop();
160	    }
161	    records
162	}
