164	/// RFC 6962 section 2.1 leaf hash: SHA-256(0x00 || data).
165	fn leaf_hash(data: &[u8]) -> [u8; 32] {
166	    let mut input = Vec::with_capacity(1 + data.len());
167	    input.push(0x00);
168	    input.extend_from_slice(data);
169	    sha256(&input)
170	}
171	
172	/// RFC 6962 section 2.1 interior node hash: SHA-256(0x01 || left || right).
173	fn node_hash(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
174	    let mut input = Vec::with_capacity(65);
175	    input.push(0x01);
176	    input.extend_from_slice(left);
177	    input.extend_from_slice(right);
178	    sha256(&input)
179	}
180	
181	/// RFC 6962 section 2.1 Merkle Tree Hash over SHA-256.
182	fn mth(leaves: &[&[u8]]) -> [u8; 32] {
183	    match leaves.len() {
184	        0 => sha256(&[]),
185	        1 => leaf_hash(leaves[0]),
186	        n => {
187	            // Largest power of two strictly smaller than n.
188	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
189	            node_hash(&mth(&leaves[..k]), &mth(&leaves[k..]))
190	        }
191	    }
192	}
193	
194	/// RFC 6962 section 2.1.1: the Merkle Tree Hash of the whole batch together
195	/// with the Merkle Audit Path for the record at `m`, computed in a single
196	/// traversal. Every leaf hash and every subtree hash is computed exactly
197	/// once: each interior hash on the path from the leaf to the root feeds both
198	/// the root computation and (for the sibling subtree) the audit path, so
199	/// producing a proof never rehashes a record byte or a subtree that already
200	/// contributed to the root.
201	///
202	/// ```text
203	/// PATH(m, [d0]) = []
204	/// PATH(m, [d0..d(n-1)]) = PATH(m, [d0..d(k-1)]) + MTH([dk..d(n-1)])   if m < k
205	///                       = PATH(m, [dk..d(n-1)]) + MTH([d0..d(k-1)])   if m >= k
206	/// ```
207	///
208	/// with k the largest power of two strictly smaller than n. Uneven batches
209	/// are handled by the recursion itself: no leaf is duplicated and no empty
210	/// record is appended to round the size up to a power of two. The returned
211	/// path is ordered from the leaf level up to the root.
212	fn root_and_path(leaves: &[&[u8]], m: usize) -> ([u8; 32], Vec<[u8; 32]>) {
213	    let n = leaves.len();
214	    assert!(m < n, "leaf index {m} out of range for {n} record(s)");
215	    let mut path = Vec::new();
216	    let root = root_and_path_rec(leaves, m, &mut path);
217	    (root, path)
218	}
219	
220	fn root_and_path_rec(leaves: &[&[u8]], m: usize, path: &mut Vec<[u8; 32]>) -> [u8; 32] {
221	    let n = leaves.len();
222	    if n == 1 {
223	        return leaf_hash(leaves[0]);
224	    }
225	    // Largest power of two strictly smaller than n.
226	    let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
227	    if m < k {
228	        let left = root_and_path_rec(&leaves[..k], m, path);
229	        let right = mth(&leaves[k..]);
230	        path.push(right);
231	        node_hash(&left, &right)
232	    } else {
233	        let left = mth(&leaves[..k]);
234	        let right = root_and_path_rec(&leaves[k..], m - k, path);
235	        path.push(left);
236	        node_hash(&left, &right)
237	    }
238	}
