240	fn hex(digest: &[u8; 32]) -> String {
241	    let mut s = String::with_capacity(64);
242	    for b in digest {
243	        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
244	        s.push(char::from_digit((b & 0x0f) as u32, 16).unwrap());
245	    }
246	    s
247	}
