270	fn sha256(data: &[u8]) -> [u8; 32] {
271	    #[cfg(test)]
272	    SHA256_CALLS.with(|c| c.set(c.get() + 1));
273	    let mut h: [u32; 8] = [
274	        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
275	        0x5be0cd19,
276	    ];
277	
278	    let bit_len = (data.len() as u64).wrapping_mul(8);
279	    let mut msg = data.to_vec();
280	    msg.push(0x80);
281	    while msg.len() % 64 != 56 {
282	        msg.push(0);
283	    }
284	    msg.extend_from_slice(&bit_len.to_be_bytes());
285	
286	    for block in msg.chunks_exact(64) {
287	        let mut w = [0u32; 64];
288	        for (i, word) in block.chunks_exact(4).enumerate() {
289	            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
290	        }
291	        for i in 16..64 {
292	            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
293	            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
294	            w[i] = w[i - 16]
295	                .wrapping_add(s0)
296	                .wrapping_add(w[i - 7])
297	                .wrapping_add(s1);
298	        }
299	
300	        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh] = h;
301	        for i in 0..64 {
302	            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
303	            let ch = (e & f) ^ ((!e) & g);
304	            let t1 = hh
305	                .wrapping_add(s1)
306	                .wrapping_add(ch)
307	                .wrapping_add(K[i])
308	                .wrapping_add(w[i]);
309	            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
310	            let maj = (a & b) ^ (a & c) ^ (b & c);
311	            let t2 = s0.wrapping_add(maj);
312	            hh = g;
313	            g = f;
314	            f = e;
315	            e = d.wrapping_add(t1);
316	            d = c;
317	            c = b;
318	            b = a;
319	            a = t1.wrapping_add(t2);
320	        }
321	
322	        h[0] = h[0].wrapping_add(a);
323	        h[1] = h[1].wrapping_add(b);
324	        h[2] = h[2].wrapping_add(c);
325	        h[3] = h[3].wrapping_add(d);
326	        h[4] = h[4].wrapping_add(e);
327	        h[5] = h[5].wrapping_add(f);
328	        h[6] = h[6].wrapping_add(g);
329	        h[7] = h[7].wrapping_add(hh);
330	    }
331	
332	    let mut out = [0u8; 32];
333	    for (i, word) in h.iter().enumerate() {
334	        out[i * 4..i * 4 + 4].copy_from_slice(&word.to_be_bytes());
335	    }
336	    out
337	}
