379	    #[test]
380	    fn sha256_known_vectors() {
381	        assert_eq!(
382	            hex_of(&sha256(b"")),
383	            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
384	        );
385	        assert_eq!(
386	            hex_of(&sha256(b"abc")),
387	            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
388	        );
389	        // Longer than one block.
390	        assert_eq!(
391	            hex_of(&sha256(
392	                b"abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq"
393	            )),
394	            "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1"
395	        );
396	    }
