437	    #[test]
438	    fn audit_paths_verify_at_every_position_for_many_sizes() {
439	        // Sizes both sides of several power-of-two boundaries (uneven sizes
440	        // must not pad with empty or duplicated trailing records).
441	        let sizes: Vec<usize> = (1..=18).chain([31, 32, 33, 63, 64, 65, 100, 127, 128, 129, 257]).collect();
442	        for n in sizes {
443	            let records: Vec<Vec<u8>> = (0..n).map(|i| format!("record-{i:04}").into_bytes()).collect();
444	            let refs: Vec<&[u8]> = records.iter().map(|r| r.as_slice()).collect();
445	            let root = mth(&refs);
446	            for m in 0..n {
447	                let (fused_root, path) = root_and_path(&refs, m);
448	                assert_eq!(
449	                    hex_of(&fused_root),
450	                    hex_of(&root),
451	                    "single-pass root must equal mth at n={n}, m={m}"
452	                );
453	                if n == 1 {
454	                    assert!(path.is_empty(), "single record must have an empty path");
455	                } else {
456	                    // Path length is bounded by the tree depth; for an even
457	                    // power-of-two batch every position sits at full depth.
458	                    let depth = usize::BITS - (n - 1).leading_zeros();
459	                    if n.is_power_of_two() {
460	                        assert_eq!(path.len(), depth as usize, "n={n}, m={m}");
461	                    } else {
462	                        assert!(path.len() <= depth as usize, "n={n}, m={m}");
463	                    }
464	                }
465	                let computed = verify_proof(refs[m], m, n, &path);
466	                assert_eq!(hex_of(&computed), hex_of(&root), "proof mismatch at n={n}, m={m}");
467	            }
468	        }
469	    }
