471	    #[test]
472	    fn proof_generation_hashes_every_leaf_and_subtree_exactly_once() {
473	        // A batch of n records has n leaf hashes and n - 1 interior node
474	        // hashes. Computing the root and one audit path in a single pass must
475	        // cost exactly 2n - 1 SHA-256 invocations: the old two-phase
476	        // implementation (mth for the root, then inclusion_path recomputing
477	        // the sibling subtrees) needed strictly more for any n >= 2.
478	        for n in [1usize, 2, 3, 4, 5, 8, 9, 10, 16, 33] {
479	            let records: Vec<Vec<u8>> = (0..n).map(|i| format!("record-{i:04}").into_bytes()).collect();
480	            let refs: Vec<&[u8]> = records.iter().map(|r| r.as_slice()).collect();
481	            for m in 0..n {
482	                SHA256_CALLS.with(|c| c.set(0));
483	                let _ = root_and_path(&refs, m);
484	                let calls = SHA256_CALLS.with(|c| c.get());
485	                assert_eq!(
486	                    calls,
487	                    2 * n - 1,
488	                    "n={n}, m={m}: expected {n} leaf + {} interior hashes, each computed once",
489	                    n - 1
490	                );
